import json, collections, pathlib
p=next(pathlib.Path('/generation-evidence/codex-trace').rglob('*.jsonl'))
top=collections.Counter(); payload=collections.Counter(); response=collections.Counter(); malformed=[]; commands=[]; finals=[]
for n,line in enumerate(p.open(),1):
    try: x=json.loads(line)
    except Exception as e: malformed.append((n,str(e))); continue
    top[x.get('type','<none>')]+=1
    pl=x.get('payload')
    if isinstance(pl,dict):
        payload[pl.get('type','<none>')]+=1
        if pl.get('type') in ('function_call','custom_tool_call'):
            commands.append((n,pl.get('name'),str(pl.get('arguments') or pl.get('input'))[:500]))
        if pl.get('type')=='response_item':
            item=pl.get('item',{})
            response[item.get('type','<none>')]+=1
        if pl.get('type') in ('agent_message','assistant_message'):
            finals.append((n,str(pl)[:500]))
print('lines', n, 'malformed', malformed)
print('top types', dict(top))
print('payload types', dict(payload))
print('response item types', dict(response))
print('tool-like calls',len(commands))
for row in commands[-80:]: print(row)
print('agent/assistant messages',len(finals))
for row in finals[-10:]: print(row)
PY
